export function snapStreet(value,min,max){return Math.max(min,Math.min(max,Math.round((value+6)/12)*12-6));}
export function streetRoute(start,point){const end={x:snapStreet(point.x,-54,54),z:snapStreet(point.z,-102,54)},intersectionZ=snapStreet(start.z,-102,54);const candidates=Math.abs(start.z-intersectionZ)>.01?[{x:start.x,z:intersectionZ},{x:end.x,z:intersectionZ},end]:[{x:end.x,z:start.z},end];return candidates.filter((p,i,a)=>Math.hypot(p.x-(i?a[i-1].x:start.x),p.z-(i?a[i-1].z:start.z))>.01);}
export function advanceStep(position,target,maximum){const distance=Math.hypot(target.x-position.x,target.z-position.z);if(distance<.001)return {x:target.x,z:target.z,moved:0,arrived:true};const moved=Math.min(maximum,distance),ratio=moved/distance;return {x:position.x+(target.x-position.x)*ratio,z:position.z+(target.z-position.z)*ratio,moved,arrived:moved>=distance};}
